438:   buildFollowers() {
439:     if (this.mapDef.noFollowers) {
440:       this.followers = [];
441:       return;
442:     }
443:     const ids = this.party.filter(m => m.id !== 'kael').map(m => m.id);
444:     const dx = this.player.dir === 'left' ? 1 : this.player.dir === 'right' ? -1 : 0;
445:     const dy = this.player.dir === 'up' ? 1 : this.player.dir === 'down' ? -1 : 0;
446:     this.trail = [];
447:     for (let i = 1; i <= Math.max(8, ids.length * 2 + 2); i++) {
448:       this.trail.push({
449:         x: this.player.px + dx * TILE * i,
450:         y: this.player.py + dy * TILE * i,
451:         dir: this.player.dir
452:       });
453:     }
454:     this.followers = ids.map((id, i) => ({
455:       id,
456:       char: id,
457:       px: this.trail[i]?.x ?? this.player.px,
458:       py: this.trail[i]?.y ?? this.player.py,
459:       dir: this.trail[i]?.dir ?? this.player.dir,
460:       frame: 0
461:     }));
462:   }
463: 
464:   updateFollowers(oldPx, oldPy, dir) {
465:     if (!this.followers.length) return;
466:     this.trail.unshift({ x: oldPx, y: oldPy, dir });
467:     if (this.trail.length > 16) this.trail.pop();
468:     this.followers.forEach((f, i) => {
469:       const p = this.trail[i] || this.trail[this.trail.length - 1];
470:       if (p) { f.px = p.x; f.py = p.y; f.dir = p.dir; f.frame = 0; }
471:     });
472:   }
