483:   canControl() {
484:     return this.scene === 'world' && !this.storyBusy && !this.dialogueActive &&
485:       !this.menuOpen && !this.shopOpen && !this.chapterOpen && !this.defeatVisible;
486:   }
487: 
488:   updateWorld(dt) {
489:     if (!this.player) return;
490:     if (this.player.moving) {
491:       this.player.progress += dt / .145;
492:       const p = Math.min(1, this.player.progress);
493:       const e = p < .5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
494:       this.player.px = this.player.fromPx + (this.player.toPx - this.player.fromPx) * e;
495:       this.player.py = this.player.fromPy + (this.player.toPy - this.player.fromPy) * e;
496:       this.player.frame = 1;
497:       if (p >= 1) {
498:         const oldPx = this.player.fromPx;
499:         const oldPy = this.player.fromPy;
500:         this.player.moving = false;
501:         this.player.progress = 0;
502:         this.player.px = this.player.toPx;
503:         this.player.py = this.player.toPy;
504:         this.player.x = Math.round((this.player.px - 16) / TILE);
505:         this.player.y = Math.round(this.player.py / TILE);
506:         this.player.frame = 0;
507:         this.steps++;
508:         this.updateFollowers(oldPx, oldPy, this.player.dir);
509:         if (this.time - this.lastStepSound > .22) {
510:           this.audio.sfx('step');
511:           this.lastStepSound = this.time;
512:         }
513:         this.afterStep();
514:       }
515:     } else if (this.canControl()) {
516:       const dir = this.inputDirection();
517:       if (dir) {
518:         this.player.dir = dir;
519:         const [dx, dy] = this.dirVec(dir);
520:         const nx = this.player.x + dx;
521:         const ny = this.player.y + dy;
522:         if (this.canWalk(nx, ny)) this.startStep(nx, ny);
523:         else this.player.frame = 0;
524:       }
525:     }
526:     this.updateInteractHint();
527:   }
528: 
529:   inputDirection() {
530:     const k = this.keys;
531:     if (this.touchDirs.has('up') || k['w'] || k['arrowup']) return 'up';
532:     if (this.touchDirs.has('down') || k['s'] || k['arrowdown']) return 'down';
533:     if (this.touchDirs.has('left') || k['a'] || k['arrowleft']) return 'left';
534:     if (this.touchDirs.has('right') || k['d'] || k['arrowright']) return 'right';
535:     return null;
536:   }
537: 
538:   dirVec(dir) {
539:     return dir === 'up' ? [0, -1] : dir === 'down' ? [0, 1] : dir === 'left' ? [-1, 0] : [1, 0];
540:   }
541: 
542:   startStep(nx, ny) {
543:     const p = this.player;
544:     p.fromPx = p.px;
545:     p.fromPy = p.py;
546:     p.toPx = nx * TILE + 16;
547:     p.toPy = ny * TILE;
548:     p.moving = true;
549:     p.progress = 0;
550:     p.frame = 1;
551:   }
552: 
553:   canWalk(tx, ty) {
554:     if (tx < 0 || ty < 0 || tx >= 32 || ty >= 18) return false;
555:     const ch = this.mapDef.tiles[ty]?.[tx] || '#';
556:     if (SOLID_TILES.has(ch)) return false;
557:     for (const p of this.mapDef.props) {
558:       if (!p.solid) continue;
559:       if (tx >= p.x && tx < p.x + (p.w || 1) && ty >= p.y && ty < p.y + (p.h || 1)) return false;
560:     }
561:     for (const n of this.mapDef.npcs) {
562:       if (this.hiddenNpcs.has(n.id)) continue;
563:       if (n.x === tx && n.y === ty) return false;
564:     }
565:     return true;
566:   }
567: 
568:   afterStep() {
569:     const px = this.player.x;
570:     const py = this.player.y;
571:     for (const t of this.mapDef.triggers || []) {
572:       if (this.firedTriggers.has(t.id)) continue;
573:       if (!this.triggerAllowed(t)) continue;
574:       if (px >= t.x && px < t.x + (t.w || 1) && py >= t.y && py < t.y + (t.h || 1)) {
575:         this.firedTriggers.add(t.id);
576:         this.runTrigger(t);
577:         return;
578:       }
579:     }
580:   }
581: 
582:   triggerAllowed(t) {
583:     if (t.action === 'toCamp') return !!this.flags.brannJoined;
584:     if (t.action === 'prisonEscape') return !!this.flags.wardenDefeated;
585:     if (t.action === 'darianBattle') return !!this.flags.vossDefeated && !this.flags.darianDefeated;
586:     if (t.action === 'lyraBattle') return !!this.flags.darianDefeated && !this.flags.lyraDefeated;
587:     return true;
588:   }
589: 
590:   runTrigger(t) {
591:     if (this.storyBusy) return;
592:     this.storyBusy = true;
593:     const actions = {
594:       prisonGuard1: () => this.storyPrisonGuard1(),
595:       prisonGuard2: () => this.storyPrisonGuard2(),
596:       wolves: () => this.storyWolves(),
597:       toCamp: () => this.storyEnterCamp(),
598:       prisonEscape: () => this.storyPrisonEscape(),
599:       vossBattle: () => this.storyVoss(),
600:       darianBattle: () => this.storyDarian(),
601:       lyraBattle: () => this.storyLyra()
602:     };
603:     const fn = actions[t.action];
604:     if (!fn) { this.storyBusy = false; return; }
605:     Promise.resolve(fn()).catch(err => {
606:       console.error(err);
607:       this.storyBusy = false;
608:       this.showToast('Algo interrompeu a história. Tente novamente.');
609:     }).finally(() => {
610:       if (this.scene !== 'battle') this.storyBusy = false;
611:       this.updateControls();
612:     });
613:   }
614: 
