120:   async propAction(prop) {
121:     if (this.storyBusy || this.dialogueActive) return;
122:     if (prop.type === 'chest') {
123:       if (this.openedChests.has(prop.id)) {
124:         await this.showDialogue([{ narration: true, text: 'O baú está vazio. Só resta poeira e o cheiro de ferro velho.' }]);
125:         return;
126:       }
127:       this.openedChests.add(prop.id);
128:       const loot = prop.loot || {};
129:       const parts = [];
130:       if (loot.gold) { this.gold += loot.gold; parts.push(`${loot.gold} de ouro`); }
131:       for (const [id, count] of Object.entries(loot)) {
132:         if (id === 'gold') continue;
133:         this.addItem(id, count);
134:         parts.push(`${count}× ${ITEMS[id]?.name || id}`);
135:       }
136:       this.audio.sfx('chest');
137:       this.updateHUD();
138:       await this.showDialogue([{ narration: true, text: `O baú se abre com um estalo. Você encontra ${parts.join(' e ')}.` }]);
139:       return;
140:     }
141:     if (prop.type === 'forge') { this.openForge(); return; }
142:     if (prop.type === 'stall') { this.openShop('merchant'); return; }
143:     if (prop.type === 'campfire') {
144:       this.storyBusy = true;
145:       this.healParty();
146:       this.audio.sfx('heal');
147:       await this.showDialogue([{ narration: true, text: 'O fogo estala. Por um instante, o grupo esquece o ferro, a coroa e o medo. PV e PM restaurados.' }]);
148:       this.storyBusy = false;
149:       return;
150:     }
151:     if (prop.type === 'bedroll') {
152:       this.storyBusy = true;
153:       this.healParty();
154:       this.saveGame(true);
155:       await this.showDialogue([{ narration: true, text: 'Kael dorme por algumas horas. O sonho é curto, mas o suficiente. PV e PM restaurados. Progresso salvo.' }]);
156:       this.storyBusy = false;
157:       return;
158:     }
159:     if (prop.type === 'shrine') {
160:       this.storyBusy = true;
161:       this.unlockLore('heart');
162:       this.healParty();
163:       this.audio.sfx('heal');
164:       await this.showDialogue([
165:         { narration: true, text: 'A pedra antiga pulsa sob suas mãos. Runas esquecidas sussurram um nome: Valdoria.' },
166:         { narration: true, text: 'Uma luz morna percorre o grupo. PV e PM restaurados.' }
167:       ]);
168:       this.storyBusy = false;
169:       return;
170:     }
171:     if (prop.type === 'stairs') {
172:       if (!this.flags.wardenDefeated) {
173:         await this.showDialogue([{ narration: true, text: 'A porta de ferro está selada. Só o Carcereiro Gorr carrega a chave.' }]);
174:       } else {
175:         await this.storyPrisonEscape();
176:       }
177:       return;
178:     }
179:     await this.showDialogue([{ narration: true, text: 'Não há nada de útil aqui.' }]);
180:   },
