69:       side: 'enemy', index, id: def.id, name: spec.name || def.name, art: def.art,
70:       hp, maxHp: hp, mp: def.mp, maxMp: def.mp,
71:       stats: { atk: def.atk, def: def.def, mag: def.mag, spd: def.spd, luck: 2 },
72:       skills: [...def.skills],
73:       xp: def.xp, gold: def.gold, boss: !!def.boss,
74:       alive: true, defending: false, taunt: 0, shield: 0,
75:       buffs: {}, statuses: {},
76:       lungeUntil: 0, flashUntil: 0, phase2: false
77:     };
