80:   async run() {
81:     this.el.ui.classList.remove('hidden');
82:     this.el.result.classList.add('hidden');
83:     this.game.audio.playMusic(this.encounter.boss ? 'boss' : 'battle');
84:     this.renderAll();
85:     this.setMessage(this.encounter.intro || 'A batalha começa!');
86:     await wait(1300);
87:     this.setMessage('');
88: 
89:     while (!this.finished) {
90:       this.round++;
91:       this.el.round.textContent = `RODADA ${this.round}`;
92:       this.buildOrder();
93:       this.renderAll();
94:       for (const unit of this.order) {
95:         if (this.finished) break;
96:         if (!unit.alive) continue;
97:         this.active = unit;
98:         this.renderAll();
99:         this.commandMode = 'root';
100:         this.pending = null;
101:         this.tickStart(unit);
102:         if (this.checkEnd()) break;
103:         if (!unit.alive) continue;
104: 
105:         if (unit.side === 'hero') {
106:           await this.heroTurn(unit);
107:         } else {
108:           await this.enemyTurn(unit);
109:         }
110:         if (this.checkEnd()) break;
111:         this.tickEnd(unit);
112:         this.renderAll();
113:         await wait(180);
114:       }
115:     }
116: 
117:     this.active = null;
118:     this.renderAll();
119:     if (this.result === 'win') {
120:       await this.victorySequence();
121:     }
122:     this.el.ui.classList.add('hidden');
123:     this.el.result.classList.add('hidden');
124:     window.removeEventListener('keydown', this.onKey);
125:     this.game.audio.playMusic(this.game.musicForScene());
126:     return this.result;
127:   }
