136:   speed(unit) {
137:     let s = unit.stats.spd;
138:     if (unit.statuses.slow) s *= .65;
139:     if (unit.buffs.spd) s *= unit.buffs.spd.mult;
140:     return s;
141:   }
142: 
143:   eff(unit, stat) {
144:     let v = unit.stats[stat] || 0;
145:     if (unit.buffs[stat]) v *= unit.buffs[stat].mult;
146:     return v;
147:   }
