149:   tickStart(unit) {
150:     unit.defending = false;
151:     for (const key of Object.keys(unit.buffs)) {
152:       unit.buffs[key].turns--;
153:       if (unit.buffs[key].turns <= 0) delete unit.buffs[key];
154:     }
155:     for (const key of Object.keys(unit.statuses)) {
156:       unit.statuses[key].turns--;
157:       if (unit.statuses[key].turns <= 0) delete unit.statuses[key];
158:     }
159:     if (unit.taunt > 0) unit.taunt--;
160:     if (unit.statuses.poison) {
161:       const dmg = Math.max(4, Math.round(unit.maxHp * .055));
162:       this.damageHp(unit, dmg);
163:       this.floatText(`-${dmg}`, unit, '#b9d47f', 18);
164:       this.addParticles(...this.pos(unit), '#8db36b', 8);
165:       this.setMessage(`${unit.name} sofre com o veneno.`);
166:     }
167:     if (unit.statuses.burn) {
168:       const dmg = Math.max(5, Math.round(unit.maxHp * .07));
169:       this.damageHp(unit, dmg);
170:       this.floatText(`-${dmg}`, unit, '#ef9a65', 18);
171:       this.addParticles(...this.pos(unit), '#e2683d', 10);
172:       this.setMessage(`${unit.name} queima nas cinzas.`);
173:     }
