190:   async enemyTurn(unit) {
191:     this.setMessage(`${unit.name} se prepara...`);
192:     this.renderActor(unit);
193:     await wait(520);
194:     const skillId = this.chooseEnemySkill(unit);
195:     const skill = ENEMY_SKILLS[skillId];
196:     if (!skill) {
197:       await this.basicEnemyAttack(unit);
198:     } else {
199:       const targets = this.resolveEnemyTargets(unit, skill);
200:       await this.useSkill(unit, skill, targets);
201:     }
202:     this.setMessage('');
203:     if (!this.finished) {
204:       await wait(260);
205:     }
206:   }
