208:   chooseEnemySkill(unit) {
209:     const usable = unit.skills.filter(id => {
210:       const sk = ENEMY_SKILLS[id];
211:       if (!sk) return false;
212:       if (sk.kind === 'buff') {
213:         const key = Object.keys(sk.buff || {})[0];
214:         if (unit.buffs[key] && unit.buffs[key].turns > 1) return false;
215:       }
216:       return true;
217:     });
218:     if (!usable.length) return 'attack';
219:     if (unit.boss && unit.phase2 && unit.id === 'lyra' && !this.barks.has('lyraRequiem') && Math.random() < .7) {
220:       this.barks.add('lyraRequiem');
221:       return 'requiem';
222:     }
223:     const weights = usable.map(id => {
224:       const sk = ENEMY_SKILLS[id];
225:       if (sk.kind === 'buff') return 1;
226:       if (sk.target === 'allEnemies') return 2;
227:       if (sk.kind === 'drain') return 2;
228:       return 4;
229:     });
230:     let total = weights.reduce((a, b) => a + b, 0);
231:     let roll = Math.random() * total;
232:     for (let i = 0; i < usable.length; i++) {
233:       roll -= weights[i];
234:       if (roll <= 0) return usable[i];
235:     }
236:     return usable[0];
237:   }
238: 
239:   resolveEnemyTargets(unit, skill) {
240:     const heroes = this.heroes.filter(h => h.alive);
241:     if (!heroes.length) return [];
242:     if (skill.target === 'self') return [unit];
243:     if (skill.target === 'allEnemies') return heroes;
244:     const taunting = heroes.filter(h => h.taunt > 0);
245:     if (taunting.length) return [pick(taunting)];
246:     if (Math.random() < .28) {
247:       return [heroes.slice().sort((a, b) => a.hp - b.hp)[0]];
248:     }
249:     return [pick(heroes)];
250:   }
