252:   async basicEnemyAttack(unit) {
253:     const targets = this.resolveEnemyTargets(unit, { target: 'enemy' });
254:     const skill = { name: 'Ataque', kind: 'phys', power: 1, target: 'enemy' };
255:     await this.useSkill(unit, skill, targets);
256:   }
