443:   targetCandidates(action) {
444:     if (!action) return [];
445:     if (action.type === 'attack') return this.enemies.filter(e => e.alive);
446:     if (action.type === 'skill') {
447:       const sk = SKILLS[action.id];
448:       if (!sk) return [];
449:       if (sk.target === 'enemy') return this.enemies.filter(e => e.alive);
450:       if (sk.target === 'ally') return this.heroes.filter(h => h.alive);
451:       if (sk.target === 'downedAlly') return this.heroes.filter(h => !h.alive);
452:       if (sk.target === 'allEnemies') return this.enemies.filter(e => e.alive);
453:       if (sk.target === 'allAllies') return this.heroes.filter(h => h.alive);
454:       return [];
455:     }
456:     if (action.type === 'item') {
457:       const it = ITEMS[action.id];
458:       if (!it) return [];
459:       if (it.kind === 'damageAll') return this.enemies.filter(e => e.alive);
460:       return this.heroes.filter(h => h.alive || it.kind === 'full');
461:     }
462:     return [];
463:   }
