465:   handleCommand(btn) {
466:     if (!this.active || this.busy) return;
467:     const act = btn.dataset.act;
468:     const unit = this.active;
469:     if (act === 'back') {
470:       this.commandMode = 'root';
471:       this.pending = null;
472:       this.renderCommands(unit);
473:       this.game.audio.sfx('cancel');
474:       return;
475:     }
476:     if (act === 'attack') {
477:       this.pending = { type: 'attack' };
478:       this.commandMode = 'target';
479:       this.renderCommands(unit);
480:       this.game.audio.sfx('click');
481:       return;
482:     }
483:     if (act === 'skills') {
484:       this.commandMode = 'skills';
485:       this.renderCommands(unit);
486:       this.game.audio.sfx('click');
487:       return;
488:     }
489:     if (act === 'items') {
490:       this.commandMode = 'items';
491:       this.renderCommands(unit);
492:       this.game.audio.sfx('click');
493:       return;
494:     }
495:     if (act === 'defend') {
496:       this.executeHeroAction(unit, { type: 'defend' }, []);
497:       return;
498:     }
499:     if (act === 'flee') {
500:       this.executeHeroAction(unit, { type: 'flee' }, []);
501:       return;
502:     }
503:     if (act === 'skill') {
504:       const sk = SKILLS[btn.dataset.id];
505:       if (!sk || unit.mp < sk.cost) return;
506:       this.pending = { type: 'skill', id: btn.dataset.id };
507:       if (sk.target === 'self') {
508:         this.executeHeroAction(unit, this.pending, [unit]);
509:       } else if (sk.target === 'allEnemies' || sk.target === 'allAllies') {
510:         this.executeHeroAction(unit, this.pending, this.targetCandidates(this.pending));
511:       } else {
512:         this.commandMode = 'target';
513:         this.renderCommands(unit);
514:         this.game.audio.sfx('click');
515:       }
516:       return;
517:     }
518:     if (act === 'item') {
519:       const it = ITEMS[btn.dataset.id];
520:       if (!it || !this.game.inventory[btn.dataset.id]) return;
521:       this.pending = { type: 'item', id: btn.dataset.id };
522:       if (it.kind === 'damageAll') {
523:         this.executeHeroAction(unit, this.pending, this.enemies.filter(e => e.alive));
524:       } else {
525:         this.commandMode = 'target';
526:         this.renderCommands(unit);
527:         this.game.audio.sfx('click');
528:       }
529:       return;
530:     }
531:     if (act === 'target') {
532:       const side = btn.dataset.side;
533:       const index = Number(btn.dataset.index);
534:       const list = side === 'hero' ? this.heroes : this.enemies;
535:       const target = list[index];
536:       if (target) this.executeHeroAction(unit, this.pending, [target]);
537:     }
538:   }
