540:   async executeHeroAction(unit, action, targets) {
541:     if (this.busy) return;
542:     this.busy = true;
543:     this.commandMode = 'root';
544:     this.pending = null;
545:     this.el.commands.innerHTML = '';
546:     try {
547:       if (action.type === 'defend') {
548:         unit.defending = true;
549:         unit.mp = Math.min(unit.maxMp, unit.mp + 6);
550:         this.setMessage(`${unit.name} ergue a guarda e recupera 6 PM.`);
551:         this.addParticles(...this.pos(unit), '#8fb6d9', 10);
552:         this.renderParty();
553:         this.renderActor(unit);
554:         await wait(720);
555:       } else if (action.type === 'flee') {
556:         const chance = Math.min(.85, .48 + this.speed(unit) * .012);
557:         if (Math.random() < chance) {
558:           this.setMessage('Vocês escapam para as sombras...');
559:           this.game.audio.sfx('cancel');
560:           await wait(900);
561:           this.finished = true;
562:           this.result = 'flee';
563:         } else {
564:           this.setMessage('A fuga falha. Não há para onde correr.');
565:           await wait(800);
566:         }
567:       } else if (action.type === 'attack') {
568:         const sk = { name: 'Ataque', kind: 'phys', power: 1, target: 'enemy', fx: 'slash' };
569:         await this.useSkill(unit, sk, targets);
570:       } else if (action.type === 'skill') {
571:         const sk = SKILLS[action.id];
572:         if (!sk) return;
573:         if (unit.mp < sk.cost) {
574:           this.setMessage('PM insuficiente.');
575:           await wait(600);
576:         } else {
577:           unit.mp -= sk.cost;
578:           await this.useSkill(unit, sk, targets);
579:         }
580:       } else if (action.type === 'item') {
581:         await this.useItem(unit, action.id, targets);
582:       }
583:     } finally {
584:       this.busy = false;
585:       this.renderParty();
586:       this.renderEnemyCards();
587:       this.renderActor(unit);
588:       if (!this.finished) {
589:         this.setMessage('');
590:         if (this.turnResolve) {
591:           const resolve = this.turnResolve;
592:           this.turnResolve = null;
593:           resolve();
594:         }
595:       } else if (this.turnResolve) {
596:         const resolve = this.turnResolve;
597:         this.turnResolve = null;
598:         resolve();
599:       }
600:     }
601:   }
