603:   async useSkill(actor, skill, targets) {
604:     if (!targets || !targets.length) return;
605:     const side = actor.side;
606:     this.setMessage(`${actor.name} usa ${skill.name}!`);
607:     actor.lungeUntil = performance.now() + 260;
608:     if (side === 'hero') {
609:       this.game.audio.sfx(skill.kind === 'magic' || skill.kind === 'heal' ? 'magic' : 'slash');
610:     } else {
611:       this.game.audio.sfx(skill.kind === 'magic' ? 'magic' : 'hit');
612:     }
613:     this.fx.shake = Math.max(this.fx.shake, skill.kind === 'phys' ? 5 : 3);
614:     await wait(280);
615: 
616:     if (skill.kind === 'phys' || skill.kind === 'magic') {
617:       const hits = skill.hits || 1;
618:       for (let h = 0; h < hits; h++) {
619:         for (const target of targets) {
620:           if (!target.alive) continue;
621:           const result = this.dealDamage(actor, target, skill);
622:           this.floatText(result.crit ? `CRÍTICO ${result.dmg}` : `${result.dmg}`, target, result.crit ? '#ffd06b' : '#f2e5cf', result.crit ? 26 : 21);
623:           this.addParticles(...this.pos(target), skill.kind === 'magic' ? '#9f87d8' : '#d5b78a', result.crit ? 18 : 10);
624:           if (result.crit) this.fx.shake = 12;
625:           if (skill.fx === 'slash' || skill.fx === 'heavy') this.slashFx(target, skill.fx === 'heavy' ? '#e7b76b' : '#f2e4c9');
626:           if (skill.fx === 'dawn') this.slashFx(target, '#f4d48e');
627:           if (skill.fx === 'quake') {
628:             this.fx.shake = 14;
629:             this.addParticles(...this.pos(target), '#a28560', 16);
630:           }
631:           this.checkBossPhase(target);
632:           if (!target.alive) this.markDead(target);
633:           this.renderEnemyCards();
634:           this.renderParty();
635:         }
636:         if (hits > 1) await wait(170);
637:       }
638:     } else if (skill.kind === 'heal' || skill.kind === 'healSelf') {
639:       const amount = skill.kind === 'healSelf'
640:         ? Math.round(actor.maxHp * skill.power)
641:         : Math.round(skill.power + this.eff(actor, 'mag') * 2.1);
642:       for (const target of targets) {
643:         if (!target.alive) continue;
644:         const before = target.hp;
645:         target.hp = Math.min(target.maxHp, target.hp + amount);
646:         const healed = target.hp - before;
647:         this.floatText(`+${healed}`, target, '#a8e29d', 23);
648:         this.addParticles(...this.pos(target), '#8fd9a1', 14);
649:       }
650:       this.game.audio.sfx('heal');
651:     } else if (skill.kind === 'shield') {
652:       const amount = Math.round(skill.power + this.eff(actor, 'mag') * 2.2);
653:       for (const target of targets) {
654:         target.shield += amount;
655:         this.floatText(`+${amount} ESCUDO`, target, '#a8d8e8', 17);
656:         this.addParticles(...this.pos(target), '#8bc6e8', 12);
657:       }
658:       this.game.audio.sfx('shield');
659:     } else if (skill.kind === 'buff') {
660:       for (const target of targets) {
661:         for (const [stat, mult] of Object.entries(skill.buff)) {
662:           if (stat === 'turns') continue;
663:           target.buffs[stat] = { mult, turns: skill.buff.turns };
664:         }
665:         this.floatText('▲ FORTALECIDO', target, '#e7c978', 16);
666:         this.addParticles(...this.pos(target), '#e2b45e', 12);
667:       }
668:       this.game.audio.sfx('shield');
669:     } else if (skill.kind === 'taunt') {
670:       actor.taunt = 2;
671:       actor.defending = true;
672:       this.floatText('PROVOCAR', actor, '#e39a68', 17);
673:       this.addParticles(...this.pos(actor), '#e2683d', 12);
674:       this.game.audio.sfx('shield');
675:     } else if (skill.kind === 'revive') {
676:       for (const target of targets) {
677:         if (target.alive) continue;
678:         target.alive = true;
679:         target.hp = Math.max(1, Math.round(target.maxHp * skill.power));
680:         this.floatText('RENASCER', target, '#f0d58d', 18);
681:         this.addParticles(...this.pos(target), '#f0d58d', 22);
682:       }
683:       this.game.audio.sfx('levelup');
684:     } else if (skill.kind === 'drain') {
685:       for (const target of targets) {
686:         if (!target.alive) continue;
687:         const result = this.dealDamage(actor, target, skill);
688:         this.floatText(`${result.dmg}`, target, '#e4b8d3', 20);
689:         const heal = Math.round(result.dmg * .55);
690:         actor.hp = Math.min(actor.maxHp, actor.hp + heal);
691:         this.floatText(`+${heal}`, actor, '#c6a5d8', 17);
692:         this.addParticles(...this.pos(target), '#a774a7', 14);
693:         this.addParticles(...this.pos(actor), '#a774a7', 8);
694:         this.checkBossPhase(target);
695:         if (!target.alive) this.markDead(target);
696:       }
697:       this.game.audio.sfx('magic');
698:     } else if (skill.kind === 'debuff') {
699:       for (const target of targets) {
700:         target.statuses.slow = { turns: 3 };
701:         this.floatText('LENTO', target, '#9fb1d7', 16);
702:         this.addParticles(...this.pos(target), '#738ab7', 12);
703:       }
704:       this.game.audio.sfx('magic');
705:     }
706: 
707:     if (skill.status) {
708:       for (const target of targets) {
709:         if (target.alive) {
710:           target.statuses[skill.status] = { turns: skill.statusTurns || 3 };
711:           this.floatText(skill.status.toUpperCase(), target, '#d99a6a', 14);
712:         }
713:       }
714:     }
715: 
716:     this.renderParty();
717:     this.renderEnemyCards();
718:     await wait(620);
719:   }
