721:   async useItem(actor, itemId, targets) {
722:     const item = ITEMS[itemId];
723:     if (!item || !this.game.inventory[itemId]) return;
724:     this.game.inventory[itemId]--;
725:     if (this.game.inventory[itemId] <= 0) delete this.game.inventory[itemId];
726:     this.setMessage(`${actor.name} usa ${item.name}.`);
727:     this.game.audio.sfx(item.kind === 'damageAll' ? 'hit' : 'heal');
728:     await wait(260);
729:     if (item.kind === 'damageAll') {
730:       for (const target of targets) {
731:         if (!target.alive) continue;
732:         const dmg = Math.round(item.amount * rand(.9, 1.1));
733:         this.damageHp(target, dmg);
734:         this.floatText(`${dmg}`, target, '#efae6a', 22);
735:         this.addParticles(...this.pos(target), '#e2683d', 14);
736:         this.checkBossPhase(target);
737:         if (!target.alive) this.markDead(target);
738:       }
739:       this.fx.shake = 10;
740:     } else {
741:       for (const target of targets) {
742:         if (item.kind === 'heal' && target.alive) {
743:           const before = target.hp;
744:           target.hp = Math.min(target.maxHp, target.hp + item.amount);
745:           this.floatText(`+${target.hp - before}`, target, '#a8e29d', 21);
746:         } else if (item.kind === 'mp' && target.alive) {
747:           const before = target.mp;
748:           target.mp = Math.min(target.maxMp, target.mp + item.amount);
749:           this.floatText(`+${target.mp - before} PM`, target, '#9cc8e9', 18);
750:         } else if (item.kind === 'full' && target.alive) {
751:           target.hp = target.maxHp;
752:           target.mp = target.maxMp;
753:           this.floatText('RESTAURADO', target, '#f0d58d', 18);
754:         } else if (item.kind === 'cure' && target.alive) {
755:           delete target.statuses.poison;
756:           delete target.statuses.burn;
757:           this.floatText('CURADO', target, '#b8d9a3', 17);
758:         }
759:         this.addParticles(...this.pos(target), '#8fd9a1', 10);
760:       }
761:     }
762:     this.renderParty();
763:     this.renderEnemyCards();
764:     await wait(560);
765:   }
