767:   dealDamage(actor, target, skill) {
768:     const magic = skill.kind === 'magic' || skill.kind === 'drain';
769:     const atk = magic ? this.eff(actor, 'mag') : this.eff(actor, 'atk');
770:     let def = magic ? target.stats.def * .32 : target.stats.def * .78;
771:     if (target.buffs.def) def *= target.buffs.def.mult;
772:     let base = atk * skill.power * (magic ? 2.25 : 2.05) - def;
773:     base = Math.max(4, base) * rand(.9, 1.1);
774:     const critChance = .045 + (actor.stats.luck || 0) * .006;
775:     const crit = Math.random() < critChance;
776:     if (crit) base *= 1.58;
777:     if (target.defending) base *= .48;
778:     let dmg = Math.max(1, Math.round(base));
779:     if (target.shield > 0) {
780:       const absorbed = Math.min(target.shield, dmg);
781:       target.shield -= absorbed;
782:       dmg -= absorbed;
783:       if (absorbed > 0) this.floatText(`-${absorbed} escudo`, target, '#9bcfe4', 14);
784:     }
785:     if (target.taunt > 0 && !target.defending) dmg = Math.round(dmg * .9);
786:     this.damageHp(target, dmg);
787:     target.flashUntil = performance.now() + 140;
788:     this.fx.flash = Math.max(this.fx.flash, .18);
789:     return { dmg, crit };
790:   }
