940:   update(dt) {
941:     this.fx.shake = Math.max(0, this.fx.shake - dt * 35);
942:     this.fx.flash = Math.max(0, this.fx.flash - dt * 2.2);
943:     for (const p of this.fx.particles) {
944:       p.life -= dt;
945:       if (p.kind === 'dot') {
946:         p.x += p.vx * dt;
947:         p.y += p.vy * dt;
948:         p.vy += p.gravity * dt;
949:       }
950:     }
951:     this.fx.particles = this.fx.particles.filter(p => p.life > 0);
952:     for (const f of this.fx.floaters) {
953:       f.life -= dt;
954:       f.y -= dt * 34;
955:     }
956:     this.fx.floaters = this.fx.floaters.filter(f => f.life > 0);
957:   }
