961:     ctx.save();
962:     if (this.fx.shake > .2) {
963:       ctx.translate(rand(-this.fx.shake, this.fx.shake), rand(-this.fx.shake * .6, this.fx.shake * .6));
964:     }
965:     drawBattleBackground(ctx, this.background, t);
966: 
967:     // active rings
968:     for (const u of [...this.heroes, ...this.enemies]) {
969:       if (!u.alive) continue;
970:       const { x, y } = this.pos(u);
971:       if (u === this.active) {
972:         ctx.save();
973:         ctx.globalAlpha = .45 + Math.sin(t * 4) * .12;
974:         ctx.strokeStyle = '#e2b45e';
975:         ctx.lineWidth = 2;
976:         ctx.beginPath();
977:         ctx.ellipse(x, y + 2, 34, 9, 0, 0, Math.PI * 2);
