986:         ctx.beginPath();
987:         ctx.arc(x, y - 40, 48 + Math.sin(t * 5) * 3, 0, Math.PI * 2);
988:         ctx.stroke();
989:         ctx.restore();
990:       }
991:       if (u.shield > 0) {
992:         ctx.save();
993:         ctx.globalAlpha = .3;
994:         ctx.strokeStyle = '#8bc6e8';
995:         ctx.lineWidth = 3;
996:         ctx.beginPath();
997:         ctx.ellipse(x, y - 38, 34, 52, 0, 0, Math.PI * 2);
998:         ctx.stroke();
999:         ctx.globalAlpha = .07;
1000:         ctx.fillStyle = '#8bc6e8';
1001:         ctx.fill();
1002:         ctx.restore();
1003:       }
1004:     }
