1006:     // heroes
1007:     for (const h of this.heroes) {
1008:       const { x, y } = this.pos(h);
1009:       let ox = 0;
1010:       if (h.lungeUntil > now) ox = 16 * ((h.lungeUntil - now) / 260);
1011:       const flash = h.flashUntil > now;
1012:       if (!h.alive) {
1013:         ctx.save();
1014:         ctx.globalAlpha = .28;
1015:         ctx.translate(x, y);
1016:         ctx.rotate(-.45);
1017:         drawCharacter(ctx, h.id, 0, 0, 'right', 0, 2, { battle: true, time: t });
1018:         ctx.restore();
1019:       } else {
1020:         if (flash) ctx.filter = 'brightness(2.2) saturate(.2)';
1021:         drawCharacter(ctx, h.id, x + ox, y, 'right', Math.floor(t * 2 + h.index) % 2, 2, { battle: true, time: t });
1022:         ctx.filter = 'none';
1023:       }
1024:       this.drawStatusIcons(h, x, y - 94);
1025:     }
1026: 
1027:     // enemies
1028:     for (const e of this.enemies) {
1029:       const { x, y } = this.pos(e);
1030:       let ox = 0;
1031:       if (e.lungeUntil > now) ox = -18 * ((e.lungeUntil - now) / 260);
1032:       const flash = e.flashUntil > now;
1033:       if (e.boss) {
1034:         ctx.save();
1035:         ctx.globalAlpha = e.alive ? .22 : .08;
1036:         const g = ctx.createRadialGradient(x, y - 80, 10, x, y - 80, 120);
1037:         g.addColorStop(0, e.id === 'lyra' ? '#b53b54' : '#d8a84f');
1038:         g.addColorStop(1, 'rgba(0,0,0,0)');
1039:         ctx.fillStyle = g;
1040:         ctx.beginPath();
1041:         ctx.arc(x, y - 80, 120, 0, Math.PI * 2);
1042:         ctx.fill();
1043:         ctx.restore();
1044:       }
1045:       drawEnemy(ctx, e.art, x + ox, y, (ENEMIES[e.id].scale || 1) * 1.0, t, flash, 1, !e.alive);
1046:       this.drawStatusIcons(e, x, y - (e.boss ? 170 : 100));
1047:     }
