1052:     if (this.fx.flash > 0) {
1053:       ctx.globalAlpha = Math.min(.7, this.fx.flash);
1054:       ctx.fillStyle = this.fx.flashColor;
1055:       ctx.fillRect(-40, -40, 1024 + 80, 576 + 80);
